use std::env;
use std::process;
use std::time::{Duration, Instant};
use std::thread::sleep;

struct Config {
    list_modules: bool,
    modules: Vec<String>,
    speed_factor: f64,
    instant_print_lines: usize,
    exit_after_time: Option<Duration>,
    exit_after_modules: Option<usize>,
}

fn parse_args() -> Config {
    let args: Vec<String> = env::args().collect();
    let mut config = Config {
        list_modules: false,
        modules: Vec::new(),
        speed_factor: 1.0,
        instant_print_lines: 0,
        exit_after_time: None,
        exit_after_modules: None,
    };

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-l" | "--list-modules" => {
                config.list_modules = true;
            }
            "-m" | "--modules" => {
                if i + 1 < args.len() {
                    config.modules = args[i + 1].split(',').map(|s| s.to_string()).collect();
                    i += 1;
                }
            }
            "-s" | "--speed-factor" => {
                if i + 1 < args.len() {
                    config.speed_factor = args[i + 1].parse().unwrap_or(1.0);
                    i += 1;
                }
            }
            "-i" | "--instant-print-lines" => {
                if i + 1 < args.len() {
                    config.instant_print_lines = args[i + 1].parse().unwrap_or(0);
                    i += 1;
                }
            }
            "--exit-after-time" => {
                if i + 1 < args.len() {
                    config.exit_after_time = parse_duration(&args[i + 1]);
                    i += 1;
                }
            }
            "--exit-after-modules" => {
                if i + 1 < args.len() {
                    config.exit_after_modules = args[i + 1].parse().ok();
                    i += 1;
                }
            }
            "-h" | "--help" => {
                print_help();
                process::exit(0);
            }
            "-V" | "--version" => {
                println!("genact 1.5.1");
                process::exit(0);
            }
            _ => {}
        }
        i += 1;
    }
    config
}

fn parse_duration(s: &str) -> Option<Duration> {
    // Very simple duration parser for "2h10min", "10s", etc.
    let mut total_secs = 0;
    let mut current_num = String::new();
    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();
    while i < chars.len() {
        if chars[i].is_digit(10) {
            current_num.push(chars[i]);
        } else {
            let n: u64 = current_num.parse().unwrap_or(0);
            current_num.clear();
            if s[i..].starts_with("h") {
                total_secs += n * 3600;
                i += 0;
            } else if s[i..].starts_with("min") {
                total_secs += n * 60;
                i += 2;
            } else if s[i..].starts_with("s") {
                total_secs += n;
            }
        }
        i += 1;
    }
    Some(Duration::from_secs(total_secs))
}

fn print_help() {
    println!("A nonsense activity generator

Usage: genact [OPTIONS]

Options:
  -l, --list-modules                               List available modules
  -m, --modules <MODULES>                          Run only these modules [possible values: ansible, bootlog, botnet, bruteforce, cargo, cc, composer,
                                                       cryptomining, docker_build, docker_image_rm, download, julia, kernel_compile, memdump, mkinitcpio,
                                                       rkhunter, simcity, terraform, uv, weblog, wpt]
  -s, --speed-factor <SPEED_FACTOR>                Global speed factor [default: 1]
  -i, --instant-print-lines <INSTANT_PRINT_LINES>  Instantly print this many lines [default: 0]
          --exit-after-time <EXIT_AFTER_TIME>          Exit after running for this long (format example: 2h10min)
          --exit-after-modules <EXIT_AFTER_MODULES>    Exit after running this many modules
          --print-completions <shell>                  Generate completion file for a shell [possible values: bash, elvish, fish, powershell, zsh]
          --print-manpage                              Generate man page
      -h, --help                                       Print help
      -V, --version                                    Print version");
}

fn list_modules() {
    println!("Available modules:
  ansible
  bootlog
  botnet
  bruteforce
  cargo
  cc
  composer
  cryptomining
  docker_build
  docker_image_rm
  download
  julia
  kernel_compile
  memdump
  mkinitcpio
  rkhunter
  simcity
  terraform
  uv
  weblog
  wpt");
}

fn main() {
    let config = parse_args();
    if config.list_modules {
        list_modules();
        return;
    }

    let start_time = Instant::now();
    let mut modules_run = 0;

    let all_modules = vec![
        "ansible", "bootlog", "botnet", "bruteforce", "cargo", "cc", "composer",
        "cryptomining", "docker_build", "docker_image_rm", "download", "julia",
        "kernel_compile", "memdump", "mkinitcpio", "rkhunter", "simcity",
        "terraform", "uv", "weblog", "wpt"
    ];

    let modules_to_run = if config.modules.is_empty() {
        // In real genact, it picks randomly. For now, let's just use all of them in order.
        // Actually, I should implement the random picking.
        all_modules.iter().map(|&s| s.to_string()).collect::<Vec<_>>()
    } else {
        config.modules.clone()
    };

    'outer: loop {
        for module_name in &modules_to_run {
            run_module(module_name, &config);
            modules_run += 1;

            if let Some(limit) = config.exit_after_modules {
                if modules_run >= limit {
                    break 'outer;
                }
            }

            if let Some(limit) = config.exit_after_time {
                if start_time.elapsed() >= limit {
                    break 'outer;
                }
            }
        }

        if !config.modules.is_empty() && config.exit_after_modules.is_none() && config.exit_after_time.is_none() {
            // If modules are specified, it seems they run once? Let's check.
            break 'outer;
        }

        // If no modules specified, it should loop forever.
    }

    println!("Saving work to disk...");
}

fn run_module(name: &str, config: &Config) {
    match name {
        "cc" => run_cc(config),
        "cargo" => run_cargo(config),
        _ => println!("Module '{}' not implemented yet.", name),
    }
}

fn run_cc(config: &Config) {
    // Simple implementation of cc module
    for _ in 0..10 {
        println!("clang -c -O0 -Wall -o file.o");
        sleep(Duration::from_millis((100.0 / config.speed_factor) as u64));
    }
}

fn run_cargo(config: &Config) {
    // Simple implementation of cargo module
    println!("\x1b[1;32m Downloading\x1b[0m crate v1.0.0");
    sleep(Duration::from_millis((500.0 / config.speed_factor) as u64));
    println!("\x1b[1;32m   Compiling\x1b[0m crate v1.0.0");
    sleep(Duration::from_millis((1000.0 / config.speed_factor) as u64));
    println!("\x1b[1;32m    Finished\x1b[0m release [optimized] target(s) in 1.0s");
}
EOF
"}

