use std::env;
use std::io::{self, Write};
use std::thread::sleep;
use std::time::{Duration, Instant};

struct Rng(u64);
impl Rng {
    fn new() -> Self {
        let start = Instant::now();
        Rng(start.elapsed().as_nanos() as u64)
    }
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        self.0
    }
    fn gen_range(&mut self, start: u64, end: u64) -> u64 {
        if start == end {
            return start;
        }
        start + (self.next() % (end - start))
    }
}

struct Config {
    modules: Vec<String>,
    speed_factor: f64,
    instant_print_lines: usize,
    exit_after_time: Option<Duration>,
    exit_after_modules: Option<usize>,
}

struct State {
    config: Config,
    lines_printed: usize,
    start_time: Instant,
    modules_finished: usize,
    rng: Rng,
}

impl State {
    fn print_line(&mut self, line: &str) {
        println!("{}", line);
        self.lines_printed += 1;
    }

    fn sleep(&mut self, ms: u64) {
        if self.lines_printed > self.config.instant_print_lines {
            sleep(Duration::from_millis(
                (ms as f64 / self.config.speed_factor) as u64,
            ));
        }
    }
}

fn parse_duration(s: &str) -> Option<Duration> {
    let mut total_secs = 0;
    let mut current_num = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i].is_digit(10) {
            current_num.push(chars[i]);
            i += 1;
        } else {
            let n: u64 = current_num.parse().unwrap_or(0);
            current_num.clear();
            if s[i..].starts_with('h') {
                total_secs += n * 3600;
                i += 1;
            } else if s[i..].starts_with("min") {
                total_secs += n * 60;
                i += 3;
            } else if s[i..].starts_with('s') {
                total_secs += n;
                i += 1;
            } else {
                i += 1;
            }
        }
    }
    Some(Duration::from_secs(total_secs))
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut config = Config {
        modules: Vec::new(),
        speed_factor: 1.0,
        instant_print_lines: 0,
        exit_after_time: None,
        exit_after_modules: None,
    };

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-l" | "--list-modules" => {
                list_modules();
                return;
            }
            "-m" | "--modules" => {
                if i + 1 < args.len() {
                    let mods: Vec<String> = args[i + 1].split(',').map(|s| s.to_string()).collect();
                    config.modules.extend(mods);
                    i += 1;
                }
            }
            "-s" | "--speed-factor" => {
                if i + 1 < args.len() {
                    config.speed_factor = args[i + 1].parse().unwrap_or(1.0);
                    i += 1;
                }
            }
            "-i" | "--instant-print-lines" => {
                if i + 1 < args.len() {
                    config.instant_print_lines = args[i + 1].parse().unwrap_or(0);
                    i += 1;
                }
            }
            "--exit-after-time" => {
                if i + 1 < args.len() {
                    config.exit_after_time = parse_duration(&args[i + 1]);
                    i += 1;
                }
            }
            "--exit-after-modules" => {
                if i + 1 < args.len() {
                    config.exit_after_modules = args[i + 1].parse().ok();
                    i += 1;
                }
            }
            "-h" | "--help" => {
                print_help();
                return;
            }
            "-V" | "--version" => {
                println!("genact 1.5.1");
                return;
            }
            _ => {}
        }
        i += 1;
    }

    let mut state = State {
        config,
        lines_printed: 0,
        start_time: Instant::now(),
        modules_finished: 0,
        rng: Rng::new(),
    };

    let all_available_modules = vec![
        "ansible", "bootlog", "botnet", "bruteforce", "cargo", "cc", "composer",
        "cryptomining", "docker_build", "docker_image_rm", "download", "julia",
        "kernel_compile", "memdump", "mkinitcpio", "rkhunter", "simcity",
        "terraform", "uv", "weblog", "wpt",
    ];

    if state.config.modules.is_empty() {
        loop {
            let idx = state.rng.gen_range(0, all_available_modules.len() as u64) as usize;
            let module = all_available_modules[idx];
            run_module(module, &mut state);
            state.modules_finished += 1;
            if let Some(limit) = state.config.exit_after_modules {
                if state.modules_finished >= limit {
                    break;
                }
            }
            if let Some(limit) = state.config.exit_after_time {
                if state.start_time.elapsed() >= limit {
                    break;
                }
            }
        }
    } else {
        let mods = state.config.modules.clone();
        for module in mods {
            run_module(&module, &mut state);
            state.modules_finished += 1;
            if let Some(limit) = state.config.exit_after_modules {
                if state.modules_finished >= limit {
                    break;
                }
            }
            if let Some(limit) = state.config.exit_after_time {
                if state.start_time.elapsed() >= limit {
                    break;
                }
            }
        }
    }

    println!("Saving work to disk...");
}

