}

fn run_memdump(state: &mut State) {
    let mut addr = state.rng.next() & 0xFFFFFFFFFFFFFFF0;
    let num_lines = state.rng.gen_range(50, 200);
    for _ in 0..num_lines {
        let mut line = format!("{:016x} ", addr);
        let mut ascii = String::new();
        for i in 0..16 {
            let b = state.rng.next() as u8;
            line.push_str(&format!(" {:02x}", b));
            if i == 7 {
                line.push(' ');
            }
            if (32..=126).contains(&b) {
                ascii.push(b as char);
            } else {
                ascii.push('.');
            }
        }
        line.push_str(&format!("  |{}|", ascii));
        state.print_line(&line);
        state.sleep(10);
        addr += 16;
    }
}

