fn run_cargo(state: &mut State) {
    let mut selected_crates = Vec::new();
    let num_crates = state.rng.gen_range(10, 50);
    for _ in 0..num_crates {
        let crate_idx = state.rng.gen_range(0, CARGO_CRATES.len() as u64) as usize;
        let v1 = state.rng.gen_range(0, 3);
        let v2 = state.rng.gen_range(0, 20);
        let v3 = state.rng.gen_range(0, 50);
        selected_crates.push((CARGO_CRATES[crate_idx], v1, v2, v3));
    }

    for (c, v1, v2, v3) in &selected_crates {
        let line = format!("\x1b[1;32m Downloading\x1b[0m {} v{}.{}.{}", c, v1, v2, v3);
        state.print_line(&line);
        let d = state.rng.gen_range(10, 100);
        state.sleep(d);
    }
    for (c, v1, v2, v3) in &selected_crates {
        let line = format!("\x1b[1;32m   Compiling\x1b[0m {} v{}.{}.{}", c, v1, v2, v3);
        state.print_line(&line);
        let d = state.rng.gen_range(50, 500);
        state.sleep(d);
    }
    let dur = state.rng.gen_range(10, 100) as f64 / 10.0;
    state.print_line(&format!(
        "\x1b[1;32m    Finished\x1b[0m release [optimized] target(s) in {}s",
        dur
    ));
}

fn run_cc(state: &mut State) {
    let compilers = ["clang", "gcc"];
    let compiler = compilers[state.rng.gen_range(0, 2) as usize];
    let num_files = state.rng.gen_range(30, 100);
    for _ in 0..num_files {
        let opts = ["-O0", "-O1", "-O2", "-O3", "-Og"];
        let opt = opts[state.rng.gen_range(0, 5) as usize];
        let n1 = state.rng.next() % 1000;
        let n2 = state.rng.next() % 1000;
        let line = format!(
            "{} -c {} -Wall -Wextra -o file_{}.o kernel/{}.c",
            compiler, opt, n1, n2
        );
        state.print_line(&line);
        let d = state.rng.gen_range(10, 100);
        state.sleep(d);
    }
    state.print_line(&format!(
        "{} -o main main.o file_1.o file_2.o -lm -lpthread",
        compiler
    ));
}

fn run_memdump(state: &mut State) {
    let mut addr = state.rng.next() & 0xFFFFFFFFFFFFFFF0;
    let num_lines = state.rng.gen_range(50, 200);
    for _ in 0..num_lines {
        let mut line = format!("{:016x} ", addr);
        let mut ascii = String::new();
        for i in 0..16 {
            let b = state.rng.next() as u8;
            line.push_str(&format!(" {:02x}", b));
            if i == 7 {
                line.push(' ');
            }
            if (32..=126).contains(&b) {
                ascii.push(b as char);
            } else {
                ascii.push('.');
            }
        }
        line.push_str(&format!("  |{}|", ascii));
        state.print_line(&line);
        state.sleep(10);
        addr += 16;
    }
}

fn run_composer(state: &mut State) {
    state.print_line("\x1b[32mLoading composer repositories with package information\x1b[0m");
    state.print_line("\x1b[32mUpdating dependencies (including require-dev)\x1b[0m");
    let packages = [
        "symfony/finder",
        "sebastian/environment",
        "myclabs/deep-copy",
        "facebook/webdriver",
    ];
    for p in &packages {
        let v1 = state.rng.gen_range(0, 10);
        let v2 = state.rng.gen_range(0, 20);
        let v3 = state.rng.gen_range(0, 50);
        let line = format!(
            "  - Installing \x1b[32m{}\x1b[0m (\x1b[33m{}.{}.{}\x1b[0m): Loading from cache",
            p, v1, v2, v3
        );
        state.print_line(&line);
        let d = state.rng.gen_range(50, 200);
        state.sleep(d);
    }
    state.print_line("\x1b[32mWriting lock file\x1b[0m");
    state.print_line("\x1b[32mGenerating autoload files\x1b[0m");
}

fn run_simcity(state: &mut State) {
    let tasks = [
        "Populating Lot Templates...",
        "Debunching Unionized Commercial Services...",
        "Computing Optimal Bin Packing...",
        "Extracting Resources...",
        "Projecting Law Enforcement Pastry Intake...",
        "Increasing Accuracy of RCI Simulators...",
        "Adjusting Bell Curves...",
        "Applying Theatre Soda Layer...",
        "Deunionizing Bulldozers...",
        "Coalescing Cloud Formations...",
    ];
    let spinners = ['/', '-', '\\', '|'];
    let colors = ["\x1b[37m", "\x1b[34m", "\x1b[32m"];
    for t in &tasks {
        let color_idx = state.rng.gen_range(0, 3) as usize;
        let color = colors[color_idx];
        for i in 0..20 {
            print!("\r[ ] {} {}", t, spinners[i % 4]);
            io::stdout().flush().unwrap();
            state.sleep(50);
        }
        println!("\r[o] {}{} OK\x1b[0m", color, t);
        state.lines_printed += 1;
    }
}

