fn run_docker_build(state: &mut State) {
    state.print_line("Sending build context to Docker daemon  14.65MB");
    state.sleep(500);
    for i in 1..6 {
        state.print_line(&format!("Step {}/10 : RUN some-command", i));
        state.print_line(" ---> Running in 6b5e19c92cbb");
        for _ in 0..5 {
            let n = state.rng.next() % 100;
            state.print_line(&format!("Output line from command {}", n));
            state.sleep(100);
        }
        let id = state.rng.next() % 0xFFFFFFFFFFFF;
        state.print_line(&format!(" ---> {:012x}", id));
    }
    state.print_line("Successfully built 6b5e19c92cbb");
}

fn run_ansible(state: &mut State) {
