            state.rng.next() % 0xFFFF,
            state.rng.next() % 0xFFFF,
            state.rng.next() % 0xFFFF,
            state.rng.next() % 0xFFFF,
            state.rng.next() % 0xFFFF,
            state.rng.next() % 0xFFFF,
            state.rng.next() % 0xFFFF
        );
        state.print_line(&format!("ok: [{}]", ip));
        state.sleep(100);
    }
}

fn run_cryptomining(state: &mut State) {
    let num_lines = state.rng.gen_range(20, 50);
    for _ in 0..num_lines {
        let time = "2026-04-29 05:15:32"; // Simplified
        let speed = state.rng.gen_range(100, 1000) as f64 / 10.0;
        let shares = state.rng.gen_range(1, 100);
        let diff = state.rng.gen_range(1, 10);
        state.print_line(&format!(
            "[{}] Speed: {} MH/s, Shares: {}/0/0, Diff: {}G",
            time, speed, shares, diff
        ));
        state.sleep(200);
    }
}

fn run_bruteforce(state: &mut State) {
    state.print_line("=> Hashes to decrypt");
    for _ in 0..3 {
        let mut hash = String::new();
        for _ in 0..64 {
            let h = state.rng.next() % 16;
            hash.push_str(&format!("{:x}", h));
        }
        state.print_line(&format!("  {}", hash));
    }
    state.print_line("");
    let mut progress = 0;
    while progress <= 100 {
        let bar_len = 30;
        let filled = (progress * bar_len) / 100;
        let mut bar = String::new();
        for i in 0..bar_len {
            if i < filled {
                bar.push('=');
            } else if i == filled {
                let spinners = ['|', '/', '-', '\\'];
                bar.push(spinners[(progress % 4) as usize]);
            } else {
                bar.push(' ');
            }
        }
        print!("\r=> Extracting Rainbow Table [{}]", bar);
        io::stdout().flush().unwrap();
        progress += 1;
        state.sleep(20);
    }
    println!("");
    state.print_line("=> Begin matching");
    for _ in 0..10 {
        let mut hash = String::new();
        for _ in 0..64 {
            let h = state.rng.next() % 16;
            hash.push_str(&format!("{:x}", h));
        }
        state.print_line(&format!(" :: \x1b[31m{}\x1b[0m ::", hash));
        state.sleep(50);
    }
}
