fn run_module(name: &str, state: &mut State) {
    match name {
        "cc" => run_cc(state),
        "cargo" => run_cargo(state),
        "memdump" => run_memdump(state),
        "composer" => run_composer(state),
        "simcity" => run_simcity(state),
        "bootlog" => run_bootlog(state),
        "docker_build" => run_docker_build(state),
        "ansible" => run_ansible(state),
        "cryptomining" => run_cryptomining(state),
        "bruteforce" => run_bruteforce(state),
        _ => {
            for _ in 0..20 {
                state.print_line(&format!("Module '{}' is currently reticulating splines...", name));
                state.sleep(100);
            }
        }
    }
}

